    try {
      await API.patch(`/rider/orders/${orderId}/action`, {
        status: newStatus,
        rider_id: rider.id,
        total_amount: totalAmount,
        payment_method: payMethod
      });
      alert(`Order status updated to ${newStatus}!`);
      fetchTasks();
