                  </div>
                  <span className="text-[10px] font-black px-2.5 py-1 rounded-lg uppercase bg-emerald-100 text-emerald-800 border border-emerald-200">
                    Status: {task.status}
                  </span>
                </div>

                <div className="space-y-1.5 text-xs bg-gray-50 p-3 rounded-2xl border">
                  <p className="font-bold text-gray-900">Customer: {task.customer_name} ({task.customer_phone})</p>
                  <p className="text-gray-600 font-medium">Full Address: {task.address}</p>
                  <p className="text-emerald-800 font-bold text-[11px]">Area / Location: {task.area_name || 'General'}</p>
                  <p className="text-gray-700 font-bold text-[11px]">Payment Method: {task.payment_method}</p>

                  <div className="flex gap-2 pt-1.5">
                    <a href={`tel:${task.customer_phone}`} className="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold flex items-center gap-1">
                      <Phone className="w-3.5 h-3.5" /> Call Customer
                    </a>
                    <a href={`https://wa.me/88${task.customer_phone}`} target="_blank" rel="noreferrer" className="px-3 py-1.5 bg-emerald-500 hover:bg-emerald-600 text-white rounded-xl font-bold flex items-center gap-1">
                      <MessageCircle className="w-3.5 h-3.5" /> WhatsApp
                    </a>
                  </div>
                </div>

                {parsedItems.length > 0 && (
                  <div className="bg-slate-50 p-3 rounded-2xl text-xs space-y-1.5 border">
                    <span className="text-[10px] font-black uppercase text-gray-400">Ordered Items:</span>
                    {parsedItems.map((it, i) => (
                      <div key={i} className="flex justify-between text-gray-800 font-semibold text-xs">
                        <span>{it.qty}x {it.name} ({it.restaurant_name})</span>
                        <span className="font-black">৳{it.price * it.qty}</span>
                      </div>
